// PART 1: JWT REFRESH TOKEN ROTATION
import jwt from 'jsonwebtoken';
import crypto from 'crypto';

const ACCESS_TOKEN_EXPIRY = '15m';
const REFRESH_TOKEN_DAYS = 7;

async function issueTokenPair(userId: string) {
  const accessToken = jwt.sign({ userId }, process.env.JWT_SECRET!, {
    expiresIn: ACCESS_TOKEN_EXPIRY
  });
  const refreshToken = crypto.randomBytes(48).toString('hex');
  const expiresAt = new Date(Date.now() + REFRESH_TOKEN_DAYS * 86400000);

  await db.query(
    'INSERT INTO refresh_tokens (token, user_id, expires_at) VALUES ($1, $2, $3)',
    [refreshToken, userId, expiresAt]
  );

  return { accessToken, refreshToken };
}

async function refreshAccessToken(refreshToken: string) {
  const stored = await db.query(
    'SELECT * FROM refresh_tokens WHERE token = $1 AND expires_at > NOW()',
    [refreshToken]
  );
  if (!stored.rows[0]) throw new Error('Invalid or expired refresh token');

  // ROTATION: delete old, insert new atomically
  await db.query('DELETE FROM refresh_tokens WHERE token = $1', [refreshToken]);
  return issueTokenPair(stored.rows[0].user_id); // issues new pair
}

async function revokeSession(refreshToken: string) {
  await db.query('DELETE FROM refresh_tokens WHERE token = $1', [refreshToken]);
}

