// BEFORE: synchronous email in request handler
// (creates the 890ms latency in POST /messages)
app.post('/messages', async (req, res) => {
  const message = await messageService.create(req.body);
  // SYNCHRONOUS: blocks the event loop for 890ms
  await emailService.sendNotification(message);
  res.json({ message }); // takes 2.1s total
});

// AFTER: async job queue (Module 28's pattern, now evidence-justified)
import Queue from 'bull';
const emailQueue = new Queue('email-notifications', {
  redis: { host: process.env.REDIS_HOST, port: 6379 }
});

app.post('/messages', async (req, res) => {
  const message = await messageService.create(req.body);
  // ASYNC: adds to queue and returns immediately (< 5ms)
  await emailQueue.add('send-notification', {
    messageId: message.id,
    recipientIds: message.workspace.memberIds
  }, {
    attempts: 3,          // Module 28: retry on failure
    backoff: { type: 'exponential', delay: 1000 }
  });
  res.json({ message }); // now takes < 100ms
});

// WORKER: processes jobs outside the request cycle
const worker = new Queue.Worker('email-notifications', async (job) => {
  const { messageId, recipientIds } = job.data;
  const message = await messageService.findById(messageId);

  // Idempotency key: if this job is retried, don't send duplicate emails
  for (const userId of recipientIds) {
    await emailService.sendNotification(message, userId, {
      idempotencyKey: `msg-${messageId}-user-${userId}`
    });
  }
});

// MEASURED IMPACT:
// Before: POST /messages p99 = 2,100ms (event loop lag = 380ms)
// After:  POST /messages p99 = 87ms   (email sent async)
// Event loop lag: 380ms -> 12ms (no longer blocked by email I/O)

