// CURRENT IMPLEMENTATION (3 queries, 1.4s at peak):
async function getWorkspaceActivity(workspaceId: string) {
  // Query 1: get recent activities
  const activities = await db.query(
    'SELECT * FROM activities WHERE workspace_id = $1 ORDER BY created_at DESC LIMIT 50',
    [workspaceId]
  );

  // Query 2+N: get each user separately (N+1 pattern)
  const enriched = await Promise.all(
    activities.rows.map(async (activity) => {
      const user = await db.query(
        'SELECT id, name, avatar_url FROM users WHERE id = $1',
        [activity.user_id]
      );
      return { ...activity, user: user.rows[0] };
    })
  );

  return enriched;
}

// EXPLAIN ANALYZE output:
// Query 1: Seq Scan on activities (50000 rows), Filter: workspace_id=$1
//   Rows Removed by Filter: 49,950 -> missing index on workspace_id!
// Queries 2-N: Index Scan on users (id=$1) -> already using index, fast

// TODO: fix both problems:
// 1. Add the missing index (as a CONCURRENTLY-safe migration)
// 2. Eliminate the N+1 by rewriting to use a JOIN

