// Wait 2 minutes for Redis to restart and BullMQ to reconnect

// 02:24 - RESTORE: re-enable email queue
// $ featureFlags.set('disable-email-queue', false)
// Monitor: POST /messages error rate returns to 0.1% -> RESOLVED

// INCIDENT 1 DURATION: 9 minutes
// USERS AFFECTED: ~3% of message sends lost email notifications
//   (messages delivered; notifications delayed during 9-minute window)

// ---

// INCIDENT 2 RESPONSE WORKFLOW:
// DISCOVERY: weekly metrics review
// Memory growth trend: 40MB/day for past 5 days -> LINEAR growth
// Linear growth = classic memory leak (not load-dependent)

// HEAP ANALYSIS:
// $ node --inspect api.js
// (capture heap snapshot, analyze in Chrome DevTools)
// Large retained objects: EventEmitter with chat.ts listeners
// each socket connection adds listeners; disconnect doesn't remove them

// ROOT CAUSE - code review:
// BEFORE (leaking):
io.on('connection', (socket) => {
  socket.on('join-room', (roomId) => {
    roomService.subscribe(roomId, socket.id); // adds event listener
  });
  // NO disconnect handler -> listeners accumulate for each connection
});

// FIX:
io.on('connection', (socket) => {
  const subscriptions: string[] = [];

  socket.on('join-room', (roomId) => {
    roomService.subscribe(roomId, socket.id);
    subscriptions.push(roomId); // track subscriptions
  });

  // Cleanup on disconnect: remove ALL listeners for this socket
  socket.on('disconnect', () => {
    subscriptions.forEach(roomId => {
      roomService.unsubscribe(roomId, socket.id);
    });
    socket.removeAllListeners(); // prevent EventEmitter leak
  });
});

// VERIFIED: memory growth rate dropped from 40MB/day to 0.3MB/day
// (0.3MB/day is normal heap fragmentation, not a leak)

